import type { Metadata } from "next";
import ThemeIcon from "./ThemeIcon";
import { ArticleCard, ProcessStep, ProjectCard, SectionTitle, StudioButton } from "./DashboardComponents";
import "./noir-habitat.css";

export const metadata: Metadata = { title: "Noir Habitat — Architecture & Interiors", description: "An original dark editorial architecture studio theme built with Coordiation." };

const serviceNames = ["Architecture", "Interior", "Landscape", "Spatial strategy"];

const process = [
  ["01", "Listen", "We document the people, rituals, place, budget, and ambitions that should shape the project.", "eye"],
  ["02", "Frame", "A clear brief turns constraints into a shared design direction and an honest project roadmap.", "layers-minimalistic"],
  ["03", "Design", "Plans, material studies, models, and prototypes make every important decision visible early.", "ruler-pen"],
  ["04", "Deliver", "We coordinate details, consultants, and site observations through construction and handover.", "shield-check"],
] as const;

export default function NoirHabitatPreview() {
  return <main className="noir-habitat co-overflow-hidden" id="top">
    <header className="nh-header co-flex co-items-center co-justify-between"><a className="nh-brand co-inline-flex co-items-center" href="#top"><b>N/H</b><span>Noir Habitat<small>Architecture &amp; interiors</small></span></a><nav className="co-flex co-items-center"><a href="#studio">Studio</a><a href="#services">Services</a><a href="#work">Work</a><a href="#contact">Contact</a></nav><StudioButton href="#contact">Start a project</StudioButton><details><summary aria-label="Open navigation"><ThemeIcon name="hamburger-menu" size={22} /></summary><div><a href="#studio">Studio</a><a href="#services">Services</a><a href="#work">Work</a><a href="#contact">Contact</a></div></details></header>
    <section className="nh-hero co-grid co-items-center"><aside><span>Established 2013</span><p>Jakarta · Singapore<br />Architecture for tropical life.</p></aside><div><p className="nh-kicker">Architecture shaped by light, material, and place.</p><h1>Spaces with<br />quiet strength.</h1><StudioButton href="#work">Explore our work</StudioButton></div><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/noir-habitat/hero.jpg" alt="Modern forest house by Noir Habitat" /><figcaption className="co-absolute co-flex co-items-center co-justify-between"><span>Canopy House · Bandung</span><ThemeIcon name="arrow-to-top-right" size={16} /></figcaption></figure></section>
    <section className="nh-manifesto co-grid" id="studio"><div><SectionTitle overline="Studio">We design for<br />how life unfolds.</SectionTitle><p>Noir Habitat is an independent architecture and interior studio creating calm, enduring places across Southeast Asia.</p></div><article><strong>01</strong><h3>Observe</h3><p>Read the site, climate, rituals, and constraints before drawing the first line.</p></article><article><strong>02</strong><h3>Refine</h3><p>Reduce every decision until structure, material, and atmosphere feel inevitable.</p></article></section>

    <section className="nh-service-strip" id="services"><div className="nh-service-track co-flex co-items-center">{[...serviceNames,...serviceNames].map((name,index)=><span className="co-flex co-items-center" key={`${name}-${index}`}>{name}<i /></span>)}</div></section>

    <section className="nh-services nh-shell"><SectionTitle overline="Services">From structure<br />to atmosphere.</SectionTitle><div className="nh-services-grid co-grid"><article className="nh-service-image co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-500 co-ease-out" src="/themes/noir-habitat/service-exterior.jpg" alt="Dark modern exterior surrounded by trees" /><span className="co-absolute">01 · Architecture</span></article><article className="nh-service-feature co-flex co-flex-col"><ThemeIcon name="sofa-2" size={42} tone="sand" /><h3>Interior</h3><p>Material, light, furniture, and movement composed as one continuous experience.</p><StudioButton href="#contact">Explore service</StudioButton></article><article className="nh-service-image co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-500 co-ease-out" src="/themes/noir-habitat/service-interior.jpg" alt="Warm minimal residential interior" /><span className="co-absolute">02 · Interior</span></article></div></section>

    <section className="nh-work nh-shell" id="work"><div className="nh-heading-row co-flex co-items-end co-justify-between"><SectionTitle overline="Selected work">Homes shaped<br />around place.</SectionTitle><p>Each project responds to climate, landscape, and the small routines that make a space feel personal.</p></div><div className="nh-project-grid co-grid"><ProjectCard image="/themes/noir-habitat/project-house.jpg" title="Canopy House" category="Bandung · Residence" wide /><ProjectCard image="/themes/noir-habitat/project-villa.jpg" title="Stone Courtyard Villa" category="Bali · Hospitality" /><ProjectCard image="/themes/noir-habitat/project-interior.jpg" title="Lightwell Residence" category="Jakarta · Interior" /></div><div className="nh-work-action co-flex co-justify-center"><StudioButton href="#contact">View all projects</StudioButton></div></section>

    <section className="nh-interiors"><div className="nh-shell"><div className="nh-heading-row co-flex co-items-end co-justify-between"><SectionTitle overline="Interior studies">Material, shadow,<br />and daily ritual.</SectionTitle><div className="nh-view-switch co-flex"><button aria-label="Grid view"><ThemeIcon name="gallery-minimalistic" size={18} /></button><button aria-label="Layer view"><ThemeIcon name="layers-minimalistic" size={18} /></button></div></div><div className="nh-interior-grid co-grid"><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-500 co-ease-out" src="/themes/noir-habitat/project-interior.jpg" alt="Minimal living space with warm wood" /><figcaption className="co-absolute">Quiet living · Jakarta</figcaption></figure><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-500 co-ease-out" src="/themes/noir-habitat/news-material.jpg" alt="Material-focused residential interior" /><figcaption className="co-absolute">Soft material · Ubud</figcaption></figure><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover co-transition co-duration-500 co-ease-out" src="/themes/noir-habitat/news-light.jpg" alt="Architectural interior shaped by daylight" /><figcaption className="co-absolute">Filtered light · Surabaya</figcaption></figure></div></div></section>

    <section className="nh-process nh-shell"><div className="nh-heading-row co-flex co-items-end co-justify-between"><SectionTitle overline="Work process">Clear steps.<br />Shared decisions.</SectionTitle><StudioButton href="#contact">Discuss a project</StudioButton></div><div className="nh-process-layout co-grid"><div>{process.map(([number,title,copy,icon])=><ProcessStep number={number} title={title} copy={copy} icon={icon} key={number} />)}</div><figure className="co-relative co-overflow-hidden"><img className="co-w-full co-h-full co-object-cover" src="/themes/noir-habitat/process.jpg" alt="Architect reviewing drawings at a studio desk" /><figcaption className="co-absolute">Every decision stays visible from brief to handover.</figcaption></figure></div></section>

    <section className="nh-testimonial co-grid co-items-center"><div><ThemeIcon name="stars" size={28} tone="sand" /><blockquote>“The home feels calm, precise, and completely ours. Noir Habitat listened beyond our words and translated the way we live into every room.”</blockquote><div className="co-flex co-items-center"><img src="/themes/noir-habitat/testimonial.jpg" alt="Amara Wijaya, Noir Habitat client" /><p><b>Amara Wijaya</b><small>Canopy House client</small></p></div></div><aside><strong>4.9</strong><span>average partner rating</span><p>32 completed residential and hospitality projects across Southeast Asia.</p></aside></section>

    <section className="nh-newsletter"><div className="nh-shell co-grid co-items-center"><div><small>Notes from the studio</small><h2>Ideas for living<br />with more intention.</h2></div><form className="co-flex co-items-center"><ThemeIcon name="letter" size={18} /><label className="sr-only" htmlFor="nh-email">Email address</label><input id="nh-email" type="email" placeholder="Your email address" /><button type="submit">Subscribe <ThemeIcon name="arrow-right" size={14} tone="dark" /></button></form></div></section>

    <section className="nh-journal nh-shell"><div className="nh-heading-row co-flex co-items-end co-justify-between"><SectionTitle overline="Journal">Details worth<br />noticing.</SectionTitle><StudioButton href="#contact">More stories</StudioButton></div><div className="nh-article-grid co-grid"><ArticleCard image="/themes/noir-habitat/news-material.jpg" date="August 18, 2026" title="Five materials that age with quiet confidence" /><ArticleCard image="/themes/noir-habitat/news-light.jpg" date="August 09, 2026" title="Designing daylight for tropical homes" /><ArticleCard image="/themes/noir-habitat/project-villa.jpg" date="July 27, 2026" title="A courtyard can change how a family gathers" /></div></section>

    <footer className="nh-footer" id="contact"><div className="nh-shell"><div className="nh-footer-lead co-flex co-items-end co-justify-between"><h2>Architecture for<br />a considered life.</h2><a className="co-inline-flex co-items-center" href="mailto:studio@noirhabitat.example">studio@noirhabitat.example <ThemeIcon name="arrow-to-top-right" size={18} /></a></div><div className="nh-footer-grid co-grid"><a className="nh-brand co-inline-flex co-items-center" href="#top"><b>N/H</b><span>Noir Habitat<small>Architecture &amp; interiors</small></span></a><div><b>Studio</b><a href="#studio">About</a><a href="#services">Services</a><a href="#work">Projects</a></div><div><b>Contact</b><a href="mailto:studio@noirhabitat.example">Email studio</a><span>Jakarta · Indonesia</span><span>+62 21 555 0184</span></div><div><b>Elsewhere</b><a href="#contact">Instagram</a><a href="#contact">LinkedIn</a><a href="#contact">ArchDaily</a></div></div><div className="nh-footer-bottom co-flex co-items-center co-justify-between"><span>© 2026 Coordiation. All rights reserved.</span><a className="co-inline-flex co-items-center" href="#top">Back to top <ThemeIcon name="arrow-to-top-right" size={13} /></a></div></div></footer>
  </main>;
}

.noir-habitat { --nh-bg:#111; --nh-panel:#1b1b1b; --nh-paper:#d8d5cf; --nh-white:#f6f4ef; --nh-muted:#98948c; --nh-sand:#b79c74; min-height:100vh; background:var(--nh-bg); color:var(--nh-white); font:15px/1.55 Arial,Helvetica,sans-serif; }
.noir-habitat *, .noir-habitat *::before, .noir-habitat *::after { box-sizing:border-box; }
.noir-habitat h1,.noir-habitat h2,.noir-habitat h3,.noir-habitat p,.noir-habitat figure { margin:0; }
.noir-habitat a { color:inherit; text-decoration:none; }
.noir-habitat img { display:block; max-width:100%; }
.noir-habitat .co-flex{display:flex}.noir-habitat .co-inline-flex{display:inline-flex}.noir-habitat .co-grid{display:grid}.noir-habitat .co-items-center{align-items:center}.noir-habitat .co-items-start{align-items:start}.noir-habitat .co-items-end{align-items:flex-end}.noir-habitat .co-justify-between{justify-content:space-between}.noir-habitat .co-justify-center{justify-content:center}.noir-habitat .co-flex-col{flex-direction:column}.noir-habitat .co-relative{position:relative}.noir-habitat .co-absolute{position:absolute}.noir-habitat .co-overflow-hidden{overflow:hidden}.noir-habitat .co-w-full{width:100%}.noir-habitat .co-h-full{height:100%}.noir-habitat .co-object-cover{object-fit:cover}.noir-habitat .co-text-center{text-align:center}.noir-habitat .co-transition{transition-property:transform,color,background-color,opacity}.noir-habitat .co-duration-300{transition-duration:.3s}.noir-habitat .co-duration-500{transition-duration:.5s}.noir-habitat .co-ease-out{transition-timing-function:cubic-bezier(.16,1,.3,1)}
.nh-icon{display:inline-block;flex:0 0 auto}.nh-icon-light{filter:brightness(0) invert(1)}.nh-icon-dark{filter:none}.nh-icon-sand{filter:brightness(0) saturate(100%) invert(66%) sepia(19%) saturate(741%) hue-rotate(357deg) brightness(92%) contrast(87%)}
.nh-header{min-height:78px;padding:0 max(28px,calc((100vw - 1240px)/2));border-bottom:1px solid #343434}.nh-brand{gap:14px}.nh-brand b{font-size:22px;letter-spacing:-.08em}.nh-brand span{display:flex;flex-direction:column;font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.nh-brand small{color:var(--nh-muted);font-size:9px;font-weight:500}.nh-header nav{gap:34px}.nh-header nav a{color:#bbb;font-size:10px;letter-spacing:.14em;text-transform:uppercase}.nh-header details{display:none}.nh-button{min-width:165px;min-height:46px;gap:24px;padding:0 16px;border:1px solid #555;font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nh-button:hover{border-color:var(--nh-sand);background:var(--nh-sand);color:#111}.nh-button:hover img{filter:none}.nh-button.is-light{background:var(--nh-paper);color:#111}
.nh-hero{grid-template-columns:.35fr .8fr 1.25fr;gap:55px;width:min(1240px,calc(100% - 56px));min-height:720px;margin:auto;padding:70px 0}.nh-hero>aside{align-self:end;padding-bottom:65px;color:var(--nh-muted);font-size:11px}.nh-hero>aside span{display:block;margin-bottom:18px;color:var(--nh-sand);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.nh-kicker{max-width:340px;margin-bottom:22px!important;color:var(--nh-muted)}.nh-hero h1{margin-bottom:40px;font-size:clamp(58px,7vw,104px);font-weight:400;letter-spacing:-.065em;line-height:.86}.nh-hero figure{height:590px}.nh-hero figure:after{position:absolute;inset:0;background:linear-gradient(transparent 55%,rgba(0,0,0,.7));content:""}.nh-hero figcaption{right:0;bottom:0;left:0;z-index:1;padding:22px;color:#fff;font-size:10px;letter-spacing:.12em;text-transform:uppercase}
.nh-manifesto{grid-template-columns:1.2fr .7fr .7fr;border-top:1px solid #333;border-bottom:1px solid #333;background:var(--nh-panel)}.nh-manifesto>div,.nh-manifesto>article{min-height:340px;padding:58px max(28px,calc((100vw - 1240px)/2)/2);border-right:1px solid #333}.nh-manifesto>div{padding-left:max(28px,calc((100vw - 1240px)/2))}.nh-manifesto>div>p{max-width:430px;margin-top:28px;color:var(--nh-muted)}.nh-section-title>p{gap:9px;margin-bottom:20px;color:var(--nh-sand);font-size:9px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.nh-section-title>p span{width:6px;height:6px;background:var(--nh-sand)}.nh-section-title h2{font-size:clamp(42px,5vw,70px);font-weight:400;letter-spacing:-.055em;line-height:.95}.nh-manifesto article strong{color:var(--nh-sand);font-size:11px}.nh-manifesto article h3{margin:90px 0 12px;font-size:27px;font-weight:400}.nh-manifesto article p{color:var(--nh-muted);font-size:13px}
.nh-shell{width:min(1240px,calc(100% - 56px));margin-inline:auto}.nh-heading-row{gap:70px;margin-bottom:52px}.nh-heading-row>p{max-width:430px;color:var(--nh-muted)}.nh-section-title h2,.nh-newsletter h2,.nh-footer h2,.nh-project h3,.nh-article h3{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3}
.nh-service-strip{overflow:hidden;border-bottom:1px solid #333;background:var(--nh-white);color:#111}.nh-service-track{width:max-content;animation:nh-marquee 30s linear infinite}.nh-service-track span{gap:30px;padding:19px 30px;font-size:clamp(25px,3vw,42px);letter-spacing:-.04em;text-transform:uppercase;white-space:nowrap}.nh-service-track i{width:7px;height:7px;background:var(--nh-sand)}
.nh-services,.nh-work,.nh-process,.nh-journal{padding:115px 0}.nh-services>.nh-section-title{margin-bottom:52px}.nh-services-grid{grid-template-columns:1fr 1fr 1fr;min-height:440px}.nh-service-image span{right:0;bottom:0;padding:12px 16px;background:rgba(17,17,17,.9);font-size:10px;letter-spacing:.1em;text-transform:uppercase}.nh-service-image:hover img,.nh-interior-grid figure:hover img,.nh-project:hover>img{transform:scale(1.045)}.nh-service-feature{justify-content:center;padding:42px;background:var(--nh-paper);color:#111}.nh-service-feature h3{margin:35px 0 14px;font-size:42px;font-weight:400;letter-spacing:-.04em}.nh-service-feature p{margin-bottom:38px;color:#5e5a53}.nh-service-feature .nh-button{margin-top:auto;border-color:#777}
.nh-work{border-top:1px solid #333}.nh-project-grid{grid-template-columns:1fr 1fr;gap:24px}.nh-project{height:480px}.nh-project.is-wide{grid-column:1 / 3;height:620px}.nh-project::after{position:absolute;inset:0;background:linear-gradient(transparent 50%,rgba(0,0,0,.76));content:""}.nh-project>div{right:0;bottom:0;left:0;z-index:1;padding:28px}.nh-project small{color:#ccc;font-size:9px;letter-spacing:.13em;text-transform:uppercase}.nh-project h3{max-width:520px;margin-top:8px;font-size:32px;font-weight:400;line-height:1}.nh-project a{position:absolute;right:26px;bottom:26px;width:42px;height:42px;border:1px solid #777}.nh-work-action{margin-top:38px}
.nh-interiors{padding:110px 0;background:var(--nh-paper);color:#111}.nh-interiors .nh-section-title>p{color:#776242}.nh-view-switch{gap:8px}.nh-view-switch button{display:grid;width:42px;height:42px;padding:0;place-items:center;border:1px solid #aaa;background:transparent}.nh-interior-grid{grid-template-columns:.8fr 1.5fr .8fr;height:510px}.nh-interior-grid figure{min-width:0}.nh-interior-grid figure+figure{border-left:8px solid var(--nh-paper)}.nh-interior-grid figcaption{right:0;bottom:0;left:0;padding:18px;background:linear-gradient(transparent,rgba(0,0,0,.8));color:#fff;font-size:10px;letter-spacing:.1em;text-transform:uppercase}
.nh-process-layout{grid-template-columns:.9fr 1.1fr;border-top:1px solid #333}.nh-process-step{grid-template-columns:50px 40px 1fr;gap:18px;padding:26px 0;border-bottom:1px solid #333}.nh-process-step>span{color:var(--nh-sand);font-size:11px}.nh-process-step h3{margin-bottom:8px;font-size:20px;font-weight:400}.nh-process-step p{max-width:470px;color:var(--nh-muted);font-size:13px}.nh-process-layout>figure{min-height:520px;margin-left:55px}.nh-process-layout figcaption{right:0;bottom:0;left:0;padding:22px;background:rgba(17,17,17,.88);font-size:12px}
.nh-testimonial{grid-template-columns:1fr 300px;gap:100px;padding:110px max(28px,calc((100vw - 1040px)/2));border-block:1px solid #333;background:var(--nh-panel)}.nh-testimonial blockquote{max-width:850px;margin:30px 0 38px;font:400 clamp(31px,4vw,55px)/1.1 Georgia,serif;letter-spacing:-.035em}.nh-testimonial>div>div{gap:14px}.nh-testimonial>div>div img{width:50px;height:50px;border-radius:50%;object-fit:cover;filter:grayscale(1)}.nh-testimonial b,.nh-testimonial small{display:block}.nh-testimonial small{color:var(--nh-muted);font-size:10px}.nh-testimonial aside{padding-left:35px;border-left:1px solid #444}.nh-testimonial aside strong{display:block;font-size:78px;font-weight:400;line-height:1}.nh-testimonial aside span{color:var(--nh-sand);font-size:10px;letter-spacing:.1em;text-transform:uppercase}.nh-testimonial aside p{margin-top:28px;color:var(--nh-muted)}
.nh-newsletter{padding:90px 0;background:#090909 url('/themes/noir-habitat/project-house.jpg') center/cover no-repeat;background-blend-mode:multiply}.nh-newsletter>.nh-shell{grid-template-columns:1fr 1fr;gap:90px}.nh-newsletter small{color:var(--nh-sand);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.nh-newsletter h2{margin-top:12px;font-size:clamp(38px,4.5vw,65px);font-weight:400;letter-spacing:-.05em;line-height:.95}.nh-newsletter form{height:58px;padding-left:18px;border:1px solid #555;background:rgba(17,17,17,.86)}.nh-newsletter input{min-width:0;height:100%;flex:1;padding:0 14px;border:0;outline:0;background:transparent;color:#fff;font:inherit}.nh-newsletter button{height:42px;margin-right:7px;padding:0 18px;border:0;background:var(--nh-paper);color:#111;font-size:10px;font-weight:800;text-transform:uppercase}.nh-newsletter button img{margin-left:12px}
.nh-article-grid{grid-template-columns:repeat(3,1fr);align-items:start;gap:20px}.nh-article{min-height:465px;padding:16px;background:var(--nh-paper);color:#111}.nh-article>img{height:235px}.nh-article>small{gap:7px;margin:20px 0 13px;color:#756d61;font-size:9px;text-transform:uppercase}.nh-article h3{margin-bottom:28px;font-size:21px;font-weight:400;line-height:1.2}.nh-article>a{gap:9px;margin-top:auto;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
.nh-footer{display:block;width:100%;margin:0;padding:0;border:0;background:#0b0b0b;color:var(--nh-white);font:inherit}.nh-footer-lead{gap:50px;padding:90px 0;border-bottom:1px solid #333}.nh-footer h2{font-size:clamp(48px,6vw,86px);font-weight:400;letter-spacing:-.06em;line-height:.88}.nh-footer-lead>a{gap:12px;padding-bottom:8px;border-bottom:1px solid #777}.nh-footer-grid{grid-template-columns:1.4fr .6fr 1fr .6fr;gap:50px;padding:55px 0}.nh-footer-grid>div{display:flex;flex-direction:column;gap:9px}.nh-footer-grid>div>b{margin-bottom:8px;color:var(--nh-sand);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.nh-footer-grid>div>a,.nh-footer-grid>div>span{color:#999;font-size:12px}.nh-footer-bottom{min-height:72px;border-top:1px solid #333;color:#777;font-size:10px}.nh-footer-bottom a{gap:8px;color:#fff}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
