@media(max-width:900px){.noir-habitat .nh-header nav,.noir-habitat .nh-header>.nh-button{display:none}.nh-header details{display:block}.nh-header details summary{list-style:none}.nh-header details div{position:absolute;right:20px;z-index:9;display:grid;width:240px;background:#222;border:1px solid #444}.nh-header details a{padding:14px 18px;border-bottom:1px solid #444}.nh-hero{grid-template-columns:1fr}.nh-hero>aside{display:none}.nh-hero figure{height:520px}.nh-manifesto{grid-template-columns:1fr}.nh-manifesto>div,.nh-manifesto>article{min-height:0;padding:55px 28px;border-right:0;border-bottom:1px solid #333}.nh-manifesto article h3{margin-top:36px}.nh-services-grid{grid-template-columns:1fr 1fr}.nh-service-image:last-child{display:none}.nh-heading-row{align-items:flex-start;flex-direction:column}.nh-project.is-wide{height:520px}.nh-interior-grid{grid-template-columns:1fr 1fr;height:470px}.nh-interior-grid figure:last-child{display:none}.nh-process-layout{grid-template-columns:1fr}.nh-process-layout>figure{min-height:480px;margin:40px 0 0}.nh-testimonial{grid-template-columns:1fr;gap:55px}.nh-testimonial aside{padding:30px 0 0;border-top:1px solid #444;border-left:0}.nh-newsletter>.nh-shell{grid-template-columns:1fr;gap:45px}.nh-footer-grid{grid-template-columns:1fr 1fr}.nh-footer-grid>.nh-brand{grid-column:1 / 3}}
